def keep_current_access(apps, schema_editor):
    """Members keep Insurance access wherever they can open the Insurance space today."""
    OrganizationMembership = apps.get_model("core", "OrganizationMembership")
    Space = apps.get_model("core", "Space")

    insurance_spaces = dict(Space.objects.filter(key="insurance").values_list("organization_id", "id"))

    allowed = []
    memberships = OrganizationMembership.objects.filter(organization_id__in=list(insurance_spaces))
    for membership in memberships.prefetch_related("accessible_spaces"):
        if membership.role == "owner":
            allowed.append(membership.id)
            continue
        space_id = insurance_spaces[membership.organization_id]
        if membership.can_view_spaces and any(s.id == space_id for s in membership.accessible_spaces.all()):
            allowed.append(membership.id)
    OrganizationMembership.objects.filter(id__in=allowed).update(can_use_insurance=True)


